export const ALL_CHARGE_TYPES: ChargeTypeRecord[] = [
  ...BASE_DATA,
  ...PHONE_SMS,
  ...PHONE_VOICE,
  ...PHONE_NUMBERS,
  ...PLATFORM_LEDGER
]
  .sort((a, b) => a.chargeType.localeCompare(b.chargeType))
  .map(item => ({
    ...item,
    flow: FLOWS[item.chargeType] || ''
  }))
